INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('eea038fa0369806a3d730b0a476703ff', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_vitamins', 'Biomolecules', 'Vitamins and coenzymes', '[]', '["vitamins","coenzymes","water soluble","NAD+","redox reactions"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Which vitamin acts as a water‑soluble coenzyme that is converted to NAD⁺ in cellular redox reactions?', '["Vitamin A", "Vitamin B2 (Riboflavin)", "Vitamin B3 (Niacin)", "Vitamin D"]', 'Vitamin B3 (Niacin)', 'Niacin (Vitamin B3) is a water‑soluble vitamin that forms the coenzyme NAD⁺, essential for oxidation‑reduction processes in metabolism.', '["Step 1: List water‑soluble vitamins (B‑complex).", "Step 2: Identify which of them participates as a precursor to NAD⁺.", "Step 3: Recognize that niacin is converted to nicotinamide adenine dinucleotide (NAD⁺).", "Step 4: Choose Vitamin B3 (Niacin) as the correct option."]', '', 'chem.biomolecules.vitamin_coenzyme', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:15.768Z', 1);
